/* Small, dependency-free pixel tools shared by the two image editors */
(function(root){
'use strict';
const clone=x=>JSON.parse(JSON.stringify(x));
function layer(w,h,name='Layer'){return {name,visible:true,pixels:Array(w*h).fill(0)}}
function create(kind='unit',size=32){const names=kind==='unit'?['Shadow','Body','Turret']:['Terrain'];return {format:'rw-pixel-project',version:1,kind,width:size,height:size,title:kind==='unit'?'scout':'terrain',fps:6,frames:[{layers:names.map(n=>layer(size,size,n))}],frame:0,layer:kind==='unit'?1:0,map:{width:16,height:12,cells:Array(192).fill(0)}}}
function validate(p){if(p?.format!=='rw-pixel-project'||p.version!==1||!['unit','map'].includes(p.kind))throw Error('Invalid pixel project');if(!Number.isInteger(p.width)||!Number.isInteger(p.height)||p.width<1||p.height<1||p.width>128||p.height>128||!Array.isArray(p.frames)||!p.frames.length||p.frames.length>24)throw Error('Canvas must be 1–128 pixels with 1–24 frames');let total=0;for(const f of p.frames){if(!Array.isArray(f.layers)||!f.layers.length||f.layers.length>8)throw Error('Use 1–8 layers');for(const l of f.layers){if(!Array.isArray(l.pixels)||l.pixels.length!==p.width*p.height||l.pixels.some(x=>!Number.isInteger(x)||x<0||x>0xffffffff))throw Error('Invalid pixel data');l.name=String(l.name||'Layer').slice(0,60);total+=l.pixels.length}}if(total>1500000)throw Error('Project is too large');if(!Number.isInteger(p.frame)||p.frame<0||p.frame>=p.frames.length)p.frame=0;if(!Number.isInteger(p.layer)||p.layer<0||p.layer>=p.frames[p.frame].layers.length)p.layer=0;const m=p.map;if(!m||![m.width,m.height].every(x=>Number.isInteger(x)&&x>0&&x<=64)||!Array.isArray(m.cells)||m.cells.length!==m.width*m.height||m.cells.some(x=>!Number.isInteger(x)||x<0||x>=p.frames.length))throw Error('Invalid map grid');p.title=String(p.title||'art').slice(0,70);p.fps=Math.min(24,Math.max(1,Number(p.fps)||6));return p}
function color(hex,alpha=255){return ((parseInt(hex.slice(1),16)<<8)|alpha)>>>0}
function hex(n){return '#'+(n>>>8).toString(16).padStart(6,'0')}
function rgba(n){return [n>>>24,(n>>>16)&255,(n>>>8)&255,n&255]}
function blend(a,b){const x=rgba(a),y=rgba(b),alpha=y[3]/255,other=x[3]/255,ao=alpha+other*(1-alpha);if(!ao)return 0;const rgb=y.slice(0,3).map((v,i)=>Math.round((v*alpha+x[i]*other*(1-alpha))/ao));return ((rgb[0]<<24)|(rgb[1]<<16)|(rgb[2]<<8)|Math.round(ao*255))>>>0}
function flatten(p,frame=p.frame){const out=Array(p.width*p.height).fill(0);for(const l of p.frames[frame].layers)if(l.visible!==false)for(let i=0;i<out.length;i++)out[i]=blend(out[i],l.pixels[i]);return out}
function point(pixels,w,h,x,y,c,symmetry=false){if(x<0||y<0||x>=w||y>=h)return;pixels[y*w+x]=c;if(symmetry)pixels[y*w+w-1-x]=c}
function line(pixels,w,h,a,b,c,symmetry=false){let [x,y]=a,[ex,ey]=b;const dx=Math.abs(ex-x),dy=-Math.abs(ey-y),sx=x<ex?1:-1,sy=y<ey?1:-1;let err=dx+dy;while(true){point(pixels,w,h,x,y,c,symmetry);if(x===ex&&y===ey)break;const e=2*err;if(e>=dy){err+=dy;x+=sx}if(e<=dx){err+=dx;y+=sy}}}
function fill(pixels,w,h,x,y,c){const old=pixels[y*w+x];if(old===c)return;const stack=[y*w+x];pixels[y*w+x]=c;while(stack.length){const i=stack.pop(),px=i%w,py=Math.floor(i/w);for(const [nx,ny]of [[px-1,py],[px+1,py],[px,py-1],[px,py+1]]){const j=ny*w+nx;if(nx>=0&&ny>=0&&nx<w&&ny<h&&pixels[j]===old){pixels[j]=c;stack.push(j)}}}}
function removeBackground(pixels,w,h,tolerance=25){const source=pixels.slice(),target=rgba(source[0]),seen=new Set(),queue=[];for(let x=0;x<w;x++)queue.push(x,(h-1)*w+x);for(let y=0;y<h;y++)queue.push(y*w,y*w+w-1);while(queue.length){const i=queue.pop();if(seen.has(i))continue;seen.add(i);const c=rgba(source[i]);if(c[3]!==0&&Math.max(...c.slice(0,3).map((v,j)=>Math.abs(v-target[j])))>tolerance)continue;pixels[i]=0;const x=i%w,y=Math.floor(i/w);if(x)queue.push(i-1);if(x<w-1)queue.push(i+1);if(y)queue.push(i-w);if(y<h-1)queue.push(i+w)}}
function bytes(pixels){const data=new Uint8ClampedArray(pixels.length*4);pixels.forEach((p,i)=>data.set(rgba(p),i*4));return data}
function fromBytes(data){const out=[];for(let i=0;i<data.length;i+=4)out.push(((data[i]<<24)|(data[i+1]<<16)|(data[i+2]<<8)|data[i+3])>>>0);return out}
function resize(p,w,h){const out=clone(p);for(const f of out.frames)for(const l of f.layers){const old=l.pixels;l.pixels=Array(w*h).fill(0);for(let y=0;y<h;y++)for(let x=0;x<w;x++)l.pixels[y*w+x]=old[Math.floor(y*p.height/h)*p.width+Math.floor(x*p.width/w)]}out.width=w;out.height=h;return validate(out)}
const api={clone,layer,create,validate,color,hex,rgba,blend,flatten,point,line,fill,removeBackground,bytes,fromBytes,resize};root.RWPixel=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
